    assertEquals("GROUP:groupKey", tuples.get(0).getKey().getUser());
    assertEquals("newrelationship", tuples.get(0).getKey().getRelation());
    assertEquals("NEWTYPE:anyObjectKey", tuples.get(0).getKey().getObject());
